def lps(s: str) -> str:
    n = len(s)
    # dp[i][j] will hold the length of the longest palindromic subsequence in s[i..j]
    dp = [[0]*n for _ in range(n)]
    # For subsequences of length 1, the longest palindrome is the char itself
    for i in range(n):
        dp[i][i] = 1

    # Build the dp table
    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = 2 + (dp[i+1][j-1] if i+1 <= j-1 else 0)
            else:
                dp[i][j] = max(dp[i+1][j], dp[i][j-1])

    # Reconstruct the palindrome from dp table
    i, j = 0, n-1
    res_front = []
    res_back = []
    while i <= j:
        if s[i] == s[j]:
            res_front.append(s[i])
            if i != j:
                res_back.append(s[j])
            i += 1
            j -= 1
        elif dp[i+1][j] >= dp[i][j-1]:
            i += 1
        else:
            j -= 1

    return "".join(res_front + res_back[::-1])

